export const envelope = [13, 40, 13];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 12;

  // Safe block placement within envelope
  const setBlock = (x, y, z, block) => {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  };

  // State attachment helper: handles pre-existing bracketed states gracefully
  const withState = (blockStr, stateStr) => {
    if (!blockStr) return blockStr;
    const bracketIdx = blockStr.indexOf("[");
    const base = bracketIdx !== -1 ? blockStr.slice(0, bracketIdx) : blockStr;
    return stateStr ? `${base}[${stateStr}]` : base;
  };

  const tm = api.theme;

  // Wood roles
  const woodPlanks = tm.wood?.planks ?? "minecraft:spruce_planks";
  const woodLog = tm.wood?.log ?? "minecraft:spruce_log";
  const woodStripped = tm.wood?.stripped ?? "minecraft:stripped_spruce_log";
  const woodStairs = tm.wood?.stairs ?? "minecraft:spruce_stairs";
  const woodSlab = tm.wood?.slab ?? "minecraft:spruce_slab";
  const woodFence = tm.wood?.fence ?? "minecraft:spruce_fence";

  // Stone & Plinth roles
  const stonePrimary = tm.stone?.primary ?? "minecraft:calcite";
  const stoneAccent = tm.stone?.accent ?? "minecraft:diorite";
  const stoneStairs = tm.stone?.stairs ?? "minecraft:stone_brick_stairs";
  const plinth = tm.ground?.plinth ?? stonePrimary;
  const revetment = tm.ground?.revetment ?? plinth;
  const pavement = tm.ground?.pavement ?? "minecraft:cobblestone";

  // Roof roles
  const roofStairs = tm.roof?.stairs ?? "minecraft:dark_prismarine_stairs";
  const roofSlab = tm.roof?.slab ?? "minecraft:dark_prismarine_slab";
  const roofSolid = tm.roof?.solid ?? "minecraft:dark_prismarine";

  // Deterministic masonry mottling (whitewashed stone with textured variation)
  const getMasonry = (x, y, z) => {
    return (x * 7 + y * 13 + z * 19) % 4 === 0 ? stoneAccent : stonePrimary;
  };

  // --- 1. FOUNDATION & PLINTH CONFORMITY (Rule 6) ---
  // Occupied ground footprint: 11x11 plinth (x: 1..11, z: 1..11) plus north entrance steps (x: 5..7, z: 0)
  for (let x = 1; x <= 11; x++) {
    for (let z = 1; z <= 11; z++) {
      const isCorner = (x === 1 || x === 11) && (z === 1 || z === 11);
      if (isCorner) continue; // Chamfered corners for Himalayan battered plinth aesthetic

      const gh = Math.round(api.heightAt(x, z));
      const groundY = Math.max(0, Math.min(H - 1, seatY + gh));

      if (groundY <= seatY) {
        // Ground falls away: build foundation down to ground
        for (let y = groundY; y < seatY; y++) {
          setBlock(x, y, z, y === groundY ? revetment : plinth);
        }
      } else {
        // Ground rises above seat plane: build up to ground level
        for (let y = seatY; y <= groundY; y++) {
          setBlock(x, y, z, plinth);
        }
      }

      // Plinth terrace deck course at seatY
      setBlock(x, seatY, z, (x === 1 || x === 11 || z === 1 || z === 11) ? pavement : plinth);
    }
  }

  // --- 2. ENTRANCE STAIRS & FRONT APPROACH (North face: z = 0..1) ---
  for (let x = 5; x <= 7; x++) {
    const gh = Math.round(api.heightAt(x, 0));
    const stepGroundY = Math.max(0, Math.min(H - 1, seatY + gh));
    const bottomY = Math.min(seatY, stepGroundY);

    // Foundation beneath steps
    for (let y = bottomY; y < seatY; y++) {
      setBlock(x, y, 0, revetment);
    }

    // Approach steps leading to door threshold at seatY + 1 (y = 13)
    setBlock(x, seatY, 0, withState(stoneStairs, "facing=south,half=bottom"));
    setBlock(x, seatY + 1, 1, withState(stoneStairs, "facing=south,half=bottom"));

    // Ensure open walkable clearance above exterior steps
    for (let y = seatY + 1; y <= seatY + 4; y++) {
      setBlock(x, y, 0, "minecraft:air");
    }
    for (let y = seatY + 2; y <= seatY + 4; y++) {
      setBlock(x, y, 1, "minecraft:air");
    }
  }

  // --- 3. LOWER TOWER SHAFT (y = 13 to 20) ---
  // Floor level at y = 13
  for (let x = 2; x <= 10; x++) {
    for (let z = 2; z <= 10; z++) {
      setBlock(x, 13, z, (x >= 4 && x <= 8 && z >= 4 && z <= 8) ? woodPlanks : stonePrimary);
    }
  }

  // Double-thick battered walls: outer boundary (x=2..10, z=2..10)
  for (let y = 13; y <= 20; y++) {
    for (let x = 2; x <= 10; x++) {
      for (let z = 2; z <= 10; z++) {
        const isWall = x <= 3 || x >= 9 || z <= 3 || z >= 9;
        if (!isWall) continue; // Interior volume left empty!

        const isOuter = x === 2 || x === 10 || z === 2 || z === 10;
        let block = getMasonry(x, y, z);

        // Dark timber horizontal tie-beams (traditional Tibetan shamar bands)
        if (y === 16 || y === 19) {
          const axis = (x === 2 || x === 10) ? "axis=z" : "axis=x";
          block = withState(woodLog, axis);
        }

        // Projecting wooden joist ends at y = 19
        if (y === 19 && isOuter && (x % 2 === 0 || z % 2 === 0)) {
          block = withState(woodStripped, "axis=y");
        }

        setBlock(x, y, z, block);
      }
    }

    // Slit windows with timber lintels on East, West, and South walls
    if (y === 16 || y === 17) {
      setBlock(2, y, 6, "minecraft:air");
      setBlock(3, y, 6, "minecraft:air");
      setBlock(10, y, 6, "minecraft:air");
      setBlock(9, y, 6, "minecraft:air");
      setBlock(6, y, 10, "minecraft:air");
      setBlock(6, y, 9, "minecraft:air");
    }
  }

  // Clear Grand Entrance Portal at North (x = 6, z = 2..3, y = 14..15)
  for (let y = 14; y <= 15; y++) {
    setBlock(6, y, 2, "minecraft:air");
    setBlock(6, y, 3, "minecraft:air");
  }
  // Heavy timber portal frame & Torana lintel
  setBlock(5, 14, 2, withState(woodLog, "axis=y"));
  setBlock(5, 15, 2, withState(woodLog, "axis=y"));
  setBlock(7, 14, 2, withState(woodLog, "axis=y"));
  setBlock(7, 15, 2, withState(woodLog, "axis=y"));
  setBlock(6, 16, 2, withState(woodLog, "axis=x"));
  setBlock(5, 16, 2, withState(woodLog, "axis=x"));
  setBlock(7, 16, 2, withState(woodLog, "axis=x"));
  // Decorative entrance eave bracket
  setBlock(6, 17, 1, withState(woodStairs, "facing=south,half=bottom"));
  setBlock(5, 17, 1, withState(woodStairs, "facing=south,half=bottom"));
  setBlock(7, 17, 1, withState(woodStairs, "facing=south,half=bottom"));

  // --- 4. UPPER BELFRY PAVILION (y = 21 to 27) ---
  // Belfry timber floor deck at y = 21
  for (let x = 2; x <= 10; x++) {
    for (let z = 2; z <= 10; z++) {
      setBlock(x, 21, z, woodPlanks);
    }
  }

  // Perimeter railing at y = 22
  for (let x = 2; x <= 10; x++) {
    setBlock(x, 22, 2, woodFence);
    setBlock(x, 22, 10, woodFence);
  }
  for (let z = 2; z <= 10; z++) {
    setBlock(2, 22, z, woodFence);
    setBlock(10, 22, z, woodFence);
  }

  // 8 Timber Colonnade Pillars (y = 22 to 26)
  const pillarCoords = [
    [2, 2], [6, 2], [10, 2],
    [2, 6],         [10, 6],
    [2, 10], [6, 10], [10, 10]
  ];
  for (const [px, pz] of pillarCoords) {
    for (let y = 22; y <= 26; y++) {
      setBlock(px, y, pz, withState(woodLog, "axis=y"));
    }
    // Tibetan bow-and-cushion bracket capitals at y = 26
    if (px === 2) setBlock(px - 1, 26, pz, withState(woodStairs, "facing=east,half=top"));
    if (px === 10) setBlock(px + 1, 26, pz, withState(woodStairs, "facing=west,half=top"));
    if (pz === 2) setBlock(px, 26, pz - 1, withState(woodStairs, "facing=south,half=top"));
    if (pz === 10) setBlock(px, 26, pz + 1, withState(woodStairs, "facing=north,half=top"));
  }

  // Heavy timber tie-beam ring & cross-beams at y = 27
  for (let x = 2; x <= 10; x++) {
    setBlock(x, 27, 2, withState(woodLog, "axis=x"));
    setBlock(x, 27, 10, withState(woodLog, "axis=x"));
    setBlock(x, 27, 6, withState(woodLog, "axis=x")); // Central bell suspension beam
    setBlock(x, 27, 8, withState(woodLog, "axis=x")); // Striker suspension beam
  }
  for (let z = 2; z <= 10; z++) {
    setBlock(2, 27, z, withState(woodLog, "axis=z"));
    setBlock(10, 27, z, withState(woodLog, "axis=z"));
    setBlock(6, 27, z, withState(woodLog, "axis=z"));
  }

  // --- 5. THE GIANT CAST BRONZE TEMPLE BELL & CLAPPER (y = 21 to 27) ---
  // Hanging forged chains
  setBlock(6, 26, 6, "minecraft:chain[axis=y]");
  setBlock(6, 25, 6, "minecraft:chain[axis=y]");
  setBlock(5, 25, 6, "minecraft:chain[axis=y]");
  setBlock(7, 25, 6, "minecraft:chain[axis=y]");

  // Bell Dragon Crown (y = 24)
  setBlock(6, 24, 6, "minecraft:cut_copper");
  setBlock(5, 24, 6, "minecraft:cut_copper_stairs[facing=west,half=bottom]");
  setBlock(7, 24, 6, "minecraft:cut_copper_stairs[facing=east,half=bottom]");
  setBlock(6, 24, 5, "minecraft:cut_copper_stairs[facing=north,half=bottom]");
  setBlock(6, 24, 7, "minecraft:cut_copper_stairs[facing=south,half=bottom]");

  // Bell Upper Waist (y = 23)
  setBlock(6, 23, 6, "minecraft:bell[attachment=ceiling,facing=north]"); // Interior functional bell
  setBlock(5, 23, 6, "minecraft:cut_copper");
  setBlock(7, 23, 6, "minecraft:cut_copper");
  setBlock(6, 23, 5, "minecraft:cut_copper");
  setBlock(6, 23, 7, "minecraft:cut_copper");
  setBlock(5, 23, 5, "minecraft:cut_copper_stairs[facing=west,half=top]");
  setBlock(7, 23, 5, "minecraft:cut_copper_stairs[facing=east,half=top]");
  setBlock(5, 23, 7, "minecraft:cut_copper_stairs[facing=west,half=top]");
  setBlock(7, 23, 7, "minecraft:cut_copper_stairs[facing=east,half=top]");

  // Bell Flared Sound Lip (y = 22)
  setBlock(6, 22, 6, "minecraft:chain[axis=y]");
  setBlock(5, 22, 6, "minecraft:cut_copper_stairs[facing=east,half=bottom]");
  setBlock(7, 22, 6, "minecraft:cut_copper_stairs[facing=west,half=bottom]");
  setBlock(6, 22, 5, "minecraft:cut_copper_stairs[facing=south,half=bottom]");
  setBlock(6, 22, 7, "minecraft:cut_copper_stairs[facing=north,half=bottom]");
  setBlock(4, 22, 6, "minecraft:cut_copper_stairs[facing=west,half=top]");
  setBlock(8, 22, 6, "minecraft:cut_copper_stairs[facing=east,half=top]");
  setBlock(6, 22, 4, "minecraft:cut_copper_stairs[facing=north,half=top]");
  setBlock(6, 22, 8, "minecraft:cut_copper_stairs[facing=south,half=top]");
  setBlock(5, 22, 5, "minecraft:cut_copper");
  setBlock(7, 22, 5, "minecraft:cut_copper");
  setBlock(5, 22, 7, "minecraft:cut_copper");
  setBlock(7, 22, 7, "minecraft:cut_copper");

  // Bell Clapper Head (y = 21)
  setBlock(6, 21, 6, "minecraft:cut_copper_slab[type=top]");

  // Suspended Horizontal Striker Beam (Monastic wooden ram)
  // Suspended at z = 8, y = 22
  for (let x = 5; x <= 7; x++) {
    setBlock(x, 22, 8, withState(woodStripped, "axis=x"));
  }
  // Striker suspension chains
  for (let y = 23; y <= 26; y++) {
    setBlock(5, y, 8, "minecraft:chain[axis=y]");
    setBlock(7, y, 8, "minecraft:chain[axis=y]");
  }

  // --- 6. FLARED GOLDEN HIP ROOF (y = 28 to 33) ---
  // Layer 0: Flared Eave Overhang (y = 28) - radius 6 (x: 0..12, z: 0..12)
  for (let x = 0; x <= 12; x++) {
    setBlock(x, 28, 0, withState(roofSlab, "type=bottom"));
    setBlock(x, 28, 12, withState(roofSlab, "type=bottom"));
  }
  for (let z = 0; z <= 12; z++) {
    setBlock(0, 28, z, withState(roofSlab, "type=bottom"));
    setBlock(12, 28, z, withState(roofSlab, "type=bottom"));
  }

  // Upturned Eave Corners (kick-up) and hanging prayer lanterns/chimes
  const cornerEaves = [[0, 0], [12, 0], [0, 12], [12, 12]];
  for (const [cx, cz] of cornerEaves) {
    setBlock(cx, 29, cz, withState(roofSlab, "type=bottom")); // Flared corner tip
    setBlock(cx, 27, cz, "minecraft:chain[axis=y]");
    setBlock(cx, 26, cz, "minecraft:lantern[hanging=true]");
  }

  // Layer 1: Slope Tier 1 (y = 29) - radius 5 (x: 1..11, z: 1..11)
  for (let x = 1; x <= 11; x++) {
    for (let z = 1; z <= 11; z++) {
      if (x === 1 || x === 11 || z === 1 || z === 11) {
        if (z === 1) setBlock(x, 29, z, withState(roofStairs, "facing=south,half=bottom"));
        else if (z === 11) setBlock(x, 29, z, withState(roofStairs, "facing=north,half=bottom"));
        else if (x === 1) setBlock(x, 29, z, withState(roofStairs, "facing=east,half=bottom"));
        else if (x === 11) setBlock(x, 29, z, withState(roofStairs, "facing=west,half=bottom"));
      } else {
        setBlock(x, 29, z, roofSolid);
      }
    }
  }

  // Layer 2: Slope Tier 2 (y = 30) - radius 4 (x: 2..10, z: 2..10)
  for (let x = 2; x <= 10; x++) {
    for (let z = 2; z <= 10; z++) {
      if (x === 2 || x === 10 || z === 2 || z === 10) {
        if (z === 2) setBlock(x, 30, z, withState(roofStairs, "facing=south,half=bottom"));
        else if (z === 10) setBlock(x, 30, z, withState(roofStairs, "facing=north,half=bottom"));
        else if (x === 2) setBlock(x, 30, z, withState(roofStairs, "facing=east,half=bottom"));
        else if (x === 10) setBlock(x, 30, z, withState(roofStairs, "facing=west,half=bottom"));
      } else {
        setBlock(x, 30, z, roofSolid);
      }
    }
  }

  // Layer 3: Slope Tier 3 (y = 31) - radius 3 (x: 3..9, z: 3..9)
  for (let x = 3; x <= 9; x++) {
    for (let z = 3; z <= 9; z++) {
      if (x === 3 || x === 9 || z === 3 || z === 9) {
        if (z === 3) setBlock(x, 31, z, withState(roofStairs, "facing=south,half=bottom"));
        else if (z === 9) setBlock(x, 31, z, withState(roofStairs, "facing=north,half=bottom"));
        else if (x === 3) setBlock(x, 31, z, withState(roofStairs, "facing=east,half=bottom"));
        else if (x === 9) setBlock(x, 31, z, withState(roofStairs, "facing=west,half=bottom"));
      } else {
        setBlock(x, 31, z, roofSolid);
      }
    }
  }

  // Layer 4: Slope Tier 4 (y = 32) - radius 2 (x: 4..8, z: 4..8)
  for (let x = 4; x <= 8; x++) {
    for (let z = 4; z <= 8; z++) {
      if (x === 4 || x === 8 || z === 4 || z === 8) {
        if (z === 4) setBlock(x, 32, z, withState(roofStairs, "facing=south,half=bottom"));
        else if (z === 8) setBlock(x, 32, z, withState(roofStairs, "facing=north,half=bottom"));
        else if (x === 4) setBlock(x, 32, z, withState(roofStairs, "facing=east,half=bottom"));
        else if (x === 8) setBlock(x, 32, z, withState(roofStairs, "facing=west,half=bottom"));
      } else {
        setBlock(x, 32, z, roofSolid);
      }
    }
  }

  // Layer 5: Peak Platform Collar (y = 33) - radius 1 (x: 5..7, z: 5..7)
  setBlock(6, 33, 5, withState(roofStairs, "facing=south,half=bottom"));
  setBlock(6, 33, 7, withState(roofStairs, "facing=north,half=bottom"));
  setBlock(5, 33, 6, withState(roofStairs, "facing=east,half=bottom"));
  setBlock(7, 33, 6, withState(roofStairs, "facing=west,half=bottom"));
  setBlock(5, 33, 5, withState(roofSlab, "type=bottom"));
  setBlock(7, 33, 5, withState(roofSlab, "type=bottom"));
  setBlock(5, 33, 7, withState(roofSlab, "type=bottom"));
  setBlock(7, 33, 7, withState(roofSlab, "type=bottom"));
  setBlock(6, 33, 6, "minecraft:gold_block");

  // --- 7. GANJIRA GOLDEN PINNACLE (DOKHANG SPIRE) (y = 34 to 37) ---
  // Lotus pedestal at y = 34
  setBlock(6, 34, 6, "minecraft:gold_block");
  setBlock(5, 34, 6, "minecraft:cut_copper_stairs[facing=east,half=bottom]");
  setBlock(7, 34, 6, "minecraft:cut_copper_stairs[facing=west,half=bottom]");
  setBlock(6, 34, 5, "minecraft:cut_copper_stairs[facing=south,half=bottom]");
  setBlock(6, 34, 7, "minecraft:cut_copper_stairs[facing=north,half=bottom]");

  // Sacred Kalasha Vase at y = 35
  setBlock(6, 35, 6, "minecraft:gold_block");
  setBlock(5, 35, 6, "minecraft:cut_copper_slab[type=bottom]");
  setBlock(7, 35, 6, "minecraft:cut_copper_slab[type=bottom]");
  setBlock(6, 35, 5, "minecraft:cut_copper_slab[type=bottom]");
  setBlock(6, 35, 7, "minecraft:cut_copper_slab[type=bottom]");

  // Golden Wheel & Parasol at y = 36
  setBlock(6, 36, 6, "minecraft:raw_gold_block");

  // Cintamani Jewel Spire at y = 37
  setBlock(6, 37, 6, "minecraft:lightning_rod[facing=up]");

  return {
    name: "Valley Bell Tower",
    seatY: seatY,
    anchors: {
      front: [6, seatY + 1, 0],
      door: [6, seatY + 1, 2],
    },
    interiors: [
      {
        min: [4, 14, 4],
        max: [8, 19, 8],
        kind: "hall",
      },
    ],
  };
}

gorge_rope_bridge.source:
export const envelope = [9, 22, 56];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 8;

  // Retrieve theme palettes with robust fallbacks
  const stone = api.theme.stone.primary || "minecraft:stone_bricks";
  const stoneAccent = api.theme.stone.accent || "minecraft:chiseled_stone_bricks";
  const stoneWall = api.theme.stone.wall || "minecraft:stone_brick_wall";
  const stoneSlab = api.theme.stone.slab || "minecraft:stone_brick_slab";
  const stoneStairs = api.theme.stone.stairs || "minecraft:stone_brick_stairs";
  const plinth = api.theme.ground.plinth || api.theme.stone.primary || "minecraft:cobblestone";

  const woodPlanks = api.theme.wood.planks || "minecraft:spruce_planks";
  const woodLog = api.theme.wood.log || "minecraft:spruce_log";
  const woodStripped = api.theme.wood.stripped || "minecraft:stripped_spruce_log";
  const woodSlab = api.theme.wood.slab || "minecraft:spruce_slab";
  const woodFence = api.theme.wood.fence || "minecraft:spruce_fence";

  const roofStairs = api.theme.roof.stairs || "minecraft:dark_oak_stairs";
  const roofSlab = api.theme.roof.slab || "minecraft:dark_oak_slab";
  const roofSolid = api.theme.roof.solid || "minecraft:dark_oak_planks";

  // Traditional Tibetan 5-color lungta (prayer flags): Sky, Wind, Fire, Water, Earth
  const PRAYER_FLAGS = [
    "minecraft:blue_wool",
    "minecraft:white_wool",
    "minecraft:red_wool",
    "minecraft:green_wool",
    "minecraft:yellow_wool"
  ];
  const PRAYER_CARPETS = [
    "minecraft:blue_carpet",
    "minecraft:white_carpet",
    "minecraft:red_carpet",
    "minecraft:green_carpet",
    "minecraft:yellow_carpet"
  ];

  // Safe clipped block writer
  function setBlock(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  // Terrain height helper conforming to seat plane
  function groundAt(x, z) {
    const h = api.heightAt(x, z);
    return Math.max(0, Math.min(H - 1, Math.round(seatY + h)));
  }

  // Build foundation column from yDown down to ground
  function buildFoundation(x, z, yDown, material = plinth) {
    const gy = groundAt(x, z);
    const minY = Math.min(yDown, gy);
    const maxY = Math.max(yDown, gy);
    for (let y = minY; y <= maxY; y++) {
      setBlock(x, y, z, material);
    }
  }

  // 1. WALKWAY HEIGHT PROFILE ACROSS THE BRIDGE
  function getDeckY(z) {
    if (z <= 4) return 8;
    if (z === 5) return 9;
    if (z === 6) return 10;
    if (z >= 7 && z <= 9) return 11;
    if (z >= 10 && z <= 13) return 12;
    if (z >= 14 && z <= 21) return 11; // North span sag
    if (z >= 22 && z <= 33) return 12; // Central pier approach & crest
    if (z >= 34 && z <= 41) return 11; // South span sag
    if (z >= 42 && z <= 45) return 12;
    if (z >= 46 && z <= 48) return 11;
    if (z === 49) return 10;
    if (z === 50) return 9;
    return 8;
  }

  // 2. ABUTMENTS (North: z = 0..11, South: z = 44..55)
  function buildAbutment(isNorth) {
    const zStart = isNorth ? 0 : 44;
    const zEnd = isNorth ? 11 : 55;
    const gateZ = isNorth ? 7 : 48;
    const innerFaceZ = isNorth ? 11 : 44;

    for (let x = 0; x < W; x++) {
      for (let z = zStart; z <= zEnd; z++) {
        // Deep foundations conforming to terrain
        buildFoundation(x, z, 8, plinth);

        const isEdgeX = (x === 1 || x === 7);
        const isOuterX = (x === 0 || x === 8);
        const isApproach = isNorth ? (z <= 5) : (z >= 50);

        // Approach roadway side retaining walls
        if (isApproach) {
          if (isEdgeX) {
            for (let y = 8; y <= 10; y++) {
              setBlock(x, y, z, stone);
            }
            setBlock(x, 11, z, stoneWall);
          } else if (x >= 2 && x <= 6) {
            setBlock(x, 7, z, plinth);
            setBlock(x, 8, z, (x === 4 ? stone : plinth));
          }
        }

        // Pylon gateway towers
        const isTowerZ = isNorth ? (z >= 6 && z <= 10) : (z >= 45 && z <= 49);
        if (isTowerZ) {
          // Battered stone masonry walls on flanks
          if (x >= 1 && x <= 2 || x >= 6 && x <= 7) {
            for (let y = 8; y <= 17; y++) {
              const blk = (y === 14 || y === 17) ? stoneAccent : stone;
              setBlock(x, y, z, blk);
            }
          }

          // Archway portal over the roadway (x = 3, 4, 5)
          if (x >= 3 && x <= 5) {
            // Road bed
            setBlock(x, 10, z, plinth);
            setBlock(x, 11, z, woodPlanks);

            // Transverse header timber beams
            if (z === gateZ) {
              setBlock(x, 15, z, woodStripped + "[axis=x]");
              setBlock(x, 16, z, stoneAccent);
            }
          }
        }
      }
    }

    // Heavy cable anchor bollards inside gateway bastions
    const anchorZ = isNorth ? 6 : 49;
    for (const bx of [2, 6]) {
      setBlock(bx, 11, anchorZ, woodLog + "[axis=y]");
      setBlock(bx, 12, anchorZ, woodLog + "[axis=y]");
      setBlock(bx, 13, anchorZ, woodStripped + "[axis=y]");
      setBlock(bx, 14, anchorZ, "minecraft:chain[axis=y]");
    }

    // Traditional Tibetan timber hip roof with flared eaves over the gateway
    const roofMinZ = isNorth ? 5 : 44;
    const roofMaxZ = isNorth ? 11 : 50;

    for (let x = 0; x < W; x++) {
      for (let z = roofMinZ; z <= roofMaxZ; z++) {
        // Eaves level
        if (x === 0 || x === 8 || z === roofMinZ || z === roofMaxZ) {
          setBlock(x, 18, z, roofStairs + "[half=bottom]");
        } else {
          setBlock(x, 18, z, roofSolid);
        }

        // Upper tier crest
        if (x >= 2 && x <= 6 && z >= roofMinZ + 2 && z <= roofMaxZ - 2) {
          setBlock(x, 19, z, roofSolid);
          if (x >= 3 && x <= 5 && z >= roofMinZ + 3 && z <= roofMaxZ - 3) {
            setBlock(x, 20, z, roofSlab + "[type=bottom]");
          }
        }
      }
    }

    // Prayer flag mast and finial at tower summit
    const mastZ = isNorth ? 8 : 47;
    setBlock(4, 20, mastZ, woodFence);
    setBlock(4, 21, mastZ, PRAYER_FLAGS[4]); // Golden/Yellow top finial

    // Corbelled timber cantilever brackets projecting out over gorge
    const corbelStep = isNorth ? [10, 11, 12, 13] : [45, 44, 43, 42];
    for (let i = 0; i < corbelStep.length; i++) {
      const cz = corbelStep[i];
      const cy = 11;
      for (const cx of [2, 3, 5, 6]) {
        setBlock(cx, cy, cz, woodLog + "[axis=z]");
      }
      // Diagonal support strut stepping back down to abutment face
      for (const cx of [2, 6]) {
        setBlock(cx, cy - 1, cz, woodStripped + "[axis=z]");
        buildFoundation(cx, cz, cy - 2, woodLog + "[axis=y]");
      }
    }
  }

  buildAbutment(true);  // North Abutment
  buildAbutment(false); // South Abutment

  // 3. CENTRAL GORGE ROCK PIER & PRAYER CHORTEN (z = 25..29)
  for (let x = 2; x <= 6; x++) {
    for (let z = 25; z <= 29; z++) {
      // Pier foundation reaching down to the bedrock/riverbed
      buildFoundation(x, z, 10, stone);

      // Battered upper pier courses
      setBlock(x, 11, z, stoneAccent);
      setBlock(x, 12, z, stone);
    }
  }

  // Glacial ice-breaker cutwater wedges
  buildFoundation(4, 24, 11, stone);
  setBlock(4, 12, 24, stoneStairs + "[facing=south,half=bottom]");
  buildFoundation(4, 30, 11, stone);
  setBlock(4, 12, 30, stoneStairs + "[facing=north,half=bottom]");

  // Transverse saddle logs on pier to carry main suspension ropes
  for (let x = 1; x <= 7; x++) {
    setBlock(x, 12, 27, woodLog + "[axis=x]");
  }

  // Prayer chorten and flag posts on central pier flanks
  for (const px of [1, 7]) {
    setBlock(px, 11, 27, stone);
    setBlock(px, 12, 27, stoneAccent);
    setBlock(px, 13, 27, woodFence);
    setBlock(px, 14, 27, woodFence);
    setBlock(px, 15, 27, PRAYER_FLAGS[px === 1 ? 0 : 2]); // Blue and Red flags
    setBlock(px, 16, 27, woodFence);
  }
  // Small shrine lantern at central pier
  setBlock(2, 13, 27, "minecraft:lantern[hanging=false]");

  // 4. TIMBER TRESTLE BENTS (Supporting mid-spans at z = 18 and z = 36)
  for (const tz of [18, 36]) {
    // Cross transom beam
    for (let x = 2; x <= 6; x++) {
      setBlock(x, 10, tz, woodLog + "[axis=x]");
    }
    // Vertical legs descending to real terrain
    for (const lx of [2, 6]) {
      buildFoundation(lx, tz, 9, woodLog + "[axis=y]");
      setBlock(lx, 11, tz, woodFence);
      setBlock(lx, 12, tz, woodFence);
    }
    // Cross sway-bracing under deck
    setBlock(3, 9, tz, woodFence);
    setBlock(4, 9, tz, woodLog + "[axis=y]");
    setBlock(5, 9, tz, woodFence);
  }

  // 5. WALKWAY DECK & TRANSOMS (z = 0 to 55)
  for (let z = 0; z < D; z++) {
    const yDeck = getDeckY(z);

    // Continuous under-deck longitudinal stringers for 6-connectivity
    for (let x = 3; x <= 5; x++) {
      setBlock(x, yDeck - 1, z, woodStripped + "[axis=z]");
    }

    // Step transition connectors
    if (z > 0) {
      const prevY = getDeckY(z - 1);
      if (prevY !== yDeck) {
        const stepMinY = Math.min(prevY, yDeck);
        const stepMaxY = Math.max(prevY, yDeck);
        for (let y = stepMinY; y <= stepMaxY; y++) {
          for (let x = 3; x <= 5; x++) {
            setBlock(x, y, z, woodPlanks);
          }
        }
      }
    }

    // Transverse timber ties / transoms every 2 blocks
    if (z % 2 === 0 && z >= 10 && z <= 45) {
      for (let x = 2; x <= 6; x++) {
        setBlock(x, yDeck - 1, z, woodLog + "[axis=x]");
      }
    }

    // Walkway surface planks
    for (let x = 3; x <= 5; x++) {
      // Natural weathered wear: occasional top slab or plank variations
      if ((x === 3 || x === 5) && (z % 7 === 3)) {
        setBlock(x, yDeck, z, woodSlab + "[type=top]");
      } else {
        setBlock(x, yDeck, z, woodPlanks);
      }
    }

    // Side safety railings and handrails (x = 2 and x = 6)
    if (z >= 9 && z <= 46) {
      for (const rx of [2, 6]) {
        // Vertical post / rope hanger
        setBlock(rx, yDeck, z, woodFence);
        // Handrail rope
        setBlock(rx, yDeck + 1, z, woodFence);

        // Connect handrail vertically to transom
        if (z % 2 === 0) {
          setBlock(rx, yDeck - 1, z, woodStripped + "[axis=y]");
        }
      }
    }
  }

  // 6. MAIN SUSPENSION CABLES & VERTICAL SUSPENDERS
  // Parabolic sag curve for suspension cables
  function getCableY(z) {
    if (z <= 8) return 17;
    if (z >= 47) return 17;

    // North span (z = 8 to 27)
    if (z < 27) {
      const u = (z - 17.5) / 9.5;
      return Math.round(13 + 4 * (u * u));
    }
    // South span (z = 27 to 47)
    const u = (z - 37) / 10;
    return Math.round(13 + 4 * (u * u));
  }

  for (let z = 7; z <= 48; z++) {
    const cY = getCableY(z);
    const dY = getDeckY(z);

    for (const cx of [2, 6]) {
      // Suspension cable segment
      setBlock(cx, cY, z, "minecraft:chain[axis=z]");

      // Vertical suspender chains / rope slings down to deck handrail
      if (z % 2 === 0 && z >= 10 && z <= 45) {
        const hTop = cY - 1;
        const hBot = dY + 1;
        for (let y = hBot; y <= hTop; y++) {
          setBlock(cx, y, z, "minecraft:chain[axis=y]");
        }
      }
    }
  }

  // 7. PRAYER FLAGS (LUNGTA) STRUNG ACROSS THE GORGE
  // (a) Fluttering flags tied along the handrails
  for (let z = 10; z <= 45; z++) {
    const dY = getDeckY(z);
    const flagColor = PRAYER_FLAGS[z % 5];
    const carpetColor = PRAYER_CARPETS[z % 5];

    // Tied to handrail at alternating intervals
    if (z % 3 === 0) {
      setBlock(2, dY + 2, z, carpetColor);
    }
    if (z % 3 === 1) {
      setBlock(6, dY + 2, z, carpetColor);
    }
    // Small wool prayer pennants along cable hangers
    if (z % 4 === 2) {
      const cY = getCableY(z);
      setBlock(2, cY - 1, z, flagColor);
      setBlock(6, cY - 1, z, flagColor);
    }
  }

  // (b) High prayer-flag lines strung overhead between the towers
  for (let z = 8; z <= 47; z++) {
    // Overhead swaying catenary
    const u = (z - 27.5) / 19.5;
    const lineY = Math.round(15 + 4 * (u * u));
    const flagColor = PRAYER_FLAGS[(z + 2) % 5];

    // Centered prayer line
    setBlock(4, lineY, z, flagColor);

    // Cross-guy lines connecting overhead line to suspension cables at quarters
    if (z === 16 || z === 27 || z === 38) {
      setBlock(3, lineY, z, "minecraft:chain[axis=x]");
      setBlock(5, lineY, z, "minecraft:chain[axis=x]");
    }
  }

  // (c) Prayer flag bunting bands adorning the pylon tower walls
  for (let x = 1; x <= 7; x++) {
    if (x >= 3 && x <= 5) continue;
    // North tower band
    setBlock(x, 15, 6, PRAYER_FLAGS[x % 5]);
    setBlock(x, 15, 10, PRAYER_FLAGS[(x + 1) % 5]);
    // South tower band
    setBlock(x, 15, 45, PRAYER_FLAGS[(x + 2) % 5]);
    setBlock(x, 15, 49, PRAYER_FLAGS[(x + 3) % 5]);
  }

  return {
    name: "gorge_rope_bridge",
    seatY: seatY,
    anchors: {
      front: [4, 8, 0],
      door: [4, 8, 0],
      back: [4, 8, 55]
    }
  };
}

