export const envelope = [10, 24, 56];

export default function build(api) {
  const size = api.size;
  const seatY = 7;

  // Palette resolution from theme with fallbacks
  const woodLog = api.theme.wood.log;
  const woodPlanks = api.theme.wood.planks;
  const woodFence = api.theme.wood.fence;
  const woodStairs = api.theme.wood.stairs;
  const woodSlab = api.theme.wood.slab;

  const stonePrimary = api.theme.stone.primary;
  const stoneAccent = api.theme.stone.accent || stonePrimary;
  const stoneStairs = api.theme.stone.stairs;
  const stoneSlab = api.theme.stone.slab;
  const stoneWall = api.theme.stone.wall;

  const groundPlinth = api.theme.ground.plinth || stonePrimary;
  const groundPavement = api.theme.ground.pavement || stonePrimary;
  const groundScree = api.theme.ground.scree || stonePrimary;
  const groundBank = api.theme.ground.bank || stonePrimary;
  const groundRevetment = api.theme.ground.revetment || stonePrimary;

  // Traditional Tibetan 5-element sacred prayer flag sequence (Dharani order):
  // Blue (Sky) -> White (Wind) -> Red (Fire) -> Green (Water) -> Yellow (Earth)
  const PRAYER_COLORS = [
    "minecraft:blue_wool",
    "minecraft:white_wool",
    "minecraft:red_wool",
    "minecraft:green_wool",
    "minecraft:yellow_wool",
  ];

  function setBlock(x, y, z, block) {
    if (x >= 0 && x < size[0] && y >= 0 && y < size[1] && z >= 0 && z < size[2]) {
      api.set(x, y, z, block);
    }
  }

  function logBlock(baseLog, axis = "y") {
    const id = baseLog.split("[")[0];
    return `${id}[axis=${axis}]`;
  }

  function stairBlock(baseStair, facing = "north", half = "bottom") {
    const id = baseStair.split("[")[0];
    return `${id}[facing=${facing},half=${half}]`;
  }

  // Ground elevation conforming strictly to heightAt(x, z)
  function getGroundY(x, z) {
    const h = api.heightAt(x, z);
    return Math.max(0, Math.min(12, Math.round(seatY + h)));
  }

  // --- 1. GORGE FLOOR, CLIFF EMBANKMENTS & FOUNDATIONS ---
  // Every column is solidly grounded down to y=0 to ensure 100% terrain conformity
  for (let z = 0; z < size[2]; z++) {
    for (let x = 0; x < size[0]; x++) {
      const gy = getGroundY(x, z);

      // Deep foundation and skirt
      for (let y = 0; y < gy; y++) {
        setBlock(x, y, z, groundRevetment);
      }

      // Surface treatment depends on zone (cliff platforms vs canyon gorge)
      if (z <= 7 || z >= 48) {
        // North & South cliff terraces
        setBlock(x, gy, z, groundPavement);
      } else {
        // Deep Canyon Gorge Floor
        // Flanking canyon side-walls at x=0,1 and x=8,9
        if (x === 0 || x === 9) {
          setBlock(x, gy, z, stonePrimary);
          setBlock(x, gy + 1, z, groundBank);
          setBlock(x, gy + 2, z, stoneWall);
        } else if (x === 1 || x === 8) {
          setBlock(x, gy, z, groundBank);
          setBlock(x, gy + 1, z, stonePrimary);
        } else {
          // Rocky riverbed scree & glacial pavement
          const hash = ((x * 37 + z * 101) % 100) / 100;
          if (hash < 0.60) {
            setBlock(x, gy, z, groundScree);
          } else if (hash < 0.85) {
            setBlock(x, gy, z, groundPavement);
          } else {
            setBlock(x, gy, z, groundBank);
          }
        }
      }
    }
  }

  // --- 2. CANYON BOULDERS & RIVERBED MANI CAIRNS ---
  const boulders = [
    { x: 3, z: 15 },
    { x: 6, z: 23, cairn: true },
    { x: 4, z: 33, cairn: true },
    { x: 6, z: 42 },
  ];

  for (const b of boulders) {
    const gy = getGroundY(b.x, b.z);
    for (let dx = -1; dx <= 1; dx++) {
      for (let dz = -1; dz <= 1; dz++) {
        if (Math.abs(dx) + Math.abs(dz) <= 1) {
          setBlock(b.x + dx, gy + 1, b.z + dz, stoneAccent);
        }
      }
    }
    setBlock(b.x, gy + 2, b.z, stonePrimary);

    if (b.cairn) {
      // Small mani prayer cairn erected on the boulder in the canyon
      setBlock(b.x, gy + 3, b.z, stoneWall);
      setBlock(b.x, gy + 4, b.z, woodFence);
      setBlock(b.x, gy + 5, b.z, PRAYER_COLORS[(b.z) % 5]);
    }
  }

  // --- 3. CLIFF EDGE PARAPETS & MANI WALLS ---
  // North retaining parapet overlooking the gorge
  for (let x = 1; x <= 8; x++) {
    const gy = getGroundY(x, 7);
    setBlock(x, gy + 1, 7, stairBlock(stoneStairs, "south", "bottom"));
  }
  // South retaining parapet looking north into the gorge
  for (let x = 1; x <= 8; x++) {
    const gy = getGroundY(x, 48);
    setBlock(x, gy + 1, 48, stairBlock(stoneStairs, "north", "bottom"));
  }

  // Mani prayer walls on cliff approaches
  for (let x = 4; x <= 6; x++) {
    const gyN = getGroundY(x, 2);
    setBlock(x, gyN + 1, 2, stonePrimary);
    setBlock(x, gyN + 2, 2, stoneSlab);

    const gyS = getGroundY(x, 53);
    setBlock(x, gyS + 1, 53, stonePrimary);
    setBlock(x, gyS + 2, 53, stoneSlab);
  }

  // --- 4. STEPPED CHORTEN BASTIONS (LHATSE) ---
  function buildBastion(cx, cz) {
    const gy = getGroundY(cx, cz);
    // 3x3 plinth
    for (let dx = -1; dx <= 1; dx++) {
      for (let dz = -1; dz <= 1; dz++) {
        setBlock(cx + dx, gy + 1, cz + dz, groundPlinth);
        setBlock(cx + dx, gy + 2, cz + dz, stonePrimary);
      }
    }
    // Accent corners
    setBlock(cx - 1, gy + 2, cz - 1, stoneAccent);
    setBlock(cx + 1, gy + 2, cz - 1, stoneAccent);
    setBlock(cx - 1, gy + 2, cz + 1, stoneAccent);
    setBlock(cx + 1, gy + 2, cz + 1, stoneAccent);

    // Stepped outward stairs
    setBlock(cx, gy + 3, cz - 1, stairBlock(stoneStairs, "north"));
    setBlock(cx, gy + 3, cz + 1, stairBlock(stoneStairs, "south"));
    setBlock(cx - 1, gy + 3, cz, stairBlock(stoneStairs, "west"));
    setBlock(cx + 1, gy + 3, cz, stairBlock(stoneStairs, "east"));

    setBlock(cx - 1, gy + 3, cz - 1, stoneSlab);
    setBlock(cx + 1, gy + 3, cz - 1, stoneSlab);
    setBlock(cx - 1, gy + 3, cz + 1, stoneSlab);
    setBlock(cx + 1, gy + 3, cz + 1, stoneSlab);

    // Tier 4 cornice
    setBlock(cx, gy + 3, cz, stonePrimary);
    setBlock(cx, gy + 4, cz, stoneWall);
  }

  // Build the four massive cliff-edge bastions
  buildBastion(3, 4);
  buildBastion(7, 4);
  buildBastion(3, 51);
  buildBastion(7, 51);

  // --- 5. TALL TIMBER MASTS & RIGGING ---
  const gyN = getGroundY(5, 4);
  const mastTopN = Math.min(22, gyN + 12);

  const gyS = getGroundY(5, 51);
  const mastTopS = Math.min(22, gyS + 12);

  // North Masts (x=3 and x=7 at z=4)
  for (const mx of [3, 7]) {
    const gy = getGroundY(mx, 4);
    for (let y = gy + 1; y <= mastTopN; y++) {
      setBlock(mx, y, 4, logBlock(woodLog, "y"));
    }
    // Gilded pinnacle finial on top of mast
    setBlock(mx, mastTopN + 1, 4, "minecraft:gold_block");
    // Cross-arm stays
    setBlock(mx - 1, mastTopN - 1, 4, woodFence);
    setBlock(mx + 1, mastTopN - 1, 4, woodFence);
    setBlock(mx - 1, mastTopN - 2, 4, stairBlock(woodStairs, "west", "top"));
    setBlock(mx + 1, mastTopN - 2, 4, stairBlock(woodStairs, "east", "top"));

    // Rear timber brace stepping back into cliff rock
    setBlock(mx, mastTopN - 4, 3, woodFence);
    setBlock(mx, mastTopN - 6, 2, woodFence);
    setBlock(mx, mastTopN - 8, 1, woodFence);
    for (let y = gy + 1; y <= mastTopN - 9; y++) {
      setBlock(mx, y, 1, stoneWall);
    }
  }

  // North arch crossbeam connecting the two masts
  for (let x = 3; x <= 7; x++) {
    setBlock(x, mastTopN - 3, 4, woodPlanks);
    setBlock(x, mastTopN - 2, 4, woodFence);
  }
  setBlock(5, mastTopN - 1, 4, logBlock(woodLog, "y"));

  // South Masts (x=3 and x=7 at z=51)
  for (const mx of [3, 7]) {
    const gy = getGroundY(mx, 51);
    for (let y = gy + 1; y <= mastTopS; y++) {
      setBlock(mx, y, 51, logBlock(woodLog, "y"));
    }
    // Gilded pinnacle finial
    setBlock(mx, mastTopS + 1, 51, "minecraft:gold_block");
    // Cross-arm stays
    setBlock(mx - 1, mastTopS - 1, 51, woodFence);
    setBlock(mx + 1, mastTopS - 1, 51, woodFence);
    setBlock(mx - 1, mastTopS - 2, 51, stairBlock(woodStairs, "west", "top"));
    setBlock(mx + 1, mastTopS - 2, 51, stairBlock(woodStairs, "east", "top"));

    // Rear timber brace stepping back south into cliff rock
    setBlock(mx, mastTopS - 4, 52, woodFence);
    setBlock(mx, mastTopS - 6, 53, woodFence);
    setBlock(mx, mastTopS - 8, 54, woodFence);
    for (let y = gy + 1; y <= mastTopS - 9; y++) {
      setBlock(mx, y, 54, stoneWall);
    }
  }

  // South arch crossbeam
  for (let x = 3; x <= 7; x++) {
    setBlock(x, mastTopS - 3, 51, woodPlanks);
    setBlock(x, mastTopS - 2, 51, woodFence);
  }
  setBlock(5, mastTopS - 1, 51, logBlock(woodLog, "y"));

  // --- 6. 6-CONNECTED CATENARY PRAYER FLAG CABLES ---
  function rasterizeCatenary(p0, p1, sag) {
    const dist = Math.hypot(p1[0] - p0[0], p1[1] - p0[1], p1[2] - p0[2]);
    const steps = Math.ceil(dist * 3);
    const voxels = [];
    let lastV = null;

    for (let i = 0; i <= steps; i++) {
      const u = i / steps;
      const lx = p0[0] + (p1[0] - p0[0]) * u;
      const ly = p0[1] + (p1[1] - p0[1]) * u;
      const lz = p0[2] + (p1[2] - p0[2]) * u;
      const sy = ly - 4 * sag * u * (1 - u);

      const ix = Math.round(lx);
      const iy = Math.round(sy);
      const iz = Math.round(lz);

      if (!lastV) {
        voxels.push([ix, iy, iz]);
        lastV = [ix, iy, iz];
      } else if (lastV[0] !== ix || lastV[1] !== iy || lastV[2] !== iz) {
        // Enforce strict 6-connectivity via Manhattan stepping
        let cx = lastV[0];
        let cy = lastV[1];
        let cz = lastV[2];

        while (cx !== ix || cy !== iy || cz !== iz) {
          const dx = ix - cx;
          const dy = iy - cy;
          const dz = iz - cz;

          const adx = Math.abs(dx);
          const ady = Math.abs(dy);
          const adz = Math.abs(dz);

          if (adx >= ady && adx >= adz) {
            cx += Math.sign(dx);
          } else if (ady >= adx && ady >= adz) {
            cy += Math.sign(dy);
          } else {
            cz += Math.sign(dz);
          }
          voxels.push([cx, cy, cz]);
        }
        lastV = [ix, iy, iz];
      }
    }
    return voxels;
  }

  function renderPrayerCable(p0, p1, sag, colorOffset) {
    const voxels = rasterizeCatenary(p0, p1, sag);

    for (let i = 0; i < voxels.length; i++) {
      const [vx, vy, vz] = voxels[i];
      // Color pattern: 2 blocks per prayer flag element
      const colorIdx = (Math.floor(i / 2) + colorOffset) % 5;
      const colorBlock = PRAYER_COLORS[colorIdx];

      setBlock(vx, vy, vz, colorBlock);

      // Fluttering flag tails whipping in canyon winds
      if (i >= 2 && i <= voxels.length - 3) {
        const gy = getGroundY(vx, vz);

        // Hanging tail
        if (i % 3 === 0 && vy - 1 > gy + 1) {
          setBlock(vx, vy - 1, vz, colorBlock);

          // Horizontal flutter tail trailing in cross-canyon wind draft
          if (i % 6 === 0) {
            const windX = (i % 4 === 0) ? vx + 1 : vx - 1;
            if (windX >= 1 && windX <= 8) {
              setBlock(windX, vy - 1, vz, colorBlock);
            }
          }
        }
      }
    }
  }

  // Cable 1: West Main High Line
  renderPrayerCable(
    [3, mastTopN - 1, 4],
    [3, mastTopS - 1, 51],
    5.5,
    0
  );

  // Cable 2: East Main High Line
  renderPrayerCable(
    [7, mastTopN - 1, 4],
    [7, mastTopS - 1, 51],
    5.5,
    2
  );

  // Cable 3: Deep Sweeping Center Cable dipping over the abyss
  renderPrayerCable(
    [5, mastTopN - 1, 4],
    [5, mastTopS - 1, 51],
    7.0,
    4
  );

  // Cable 4: Diagonal Cross-Gorge Cable (West to East)
  renderPrayerCable(
    [3, mastTopN - 2, 5],
    [7, mastTopS - 2, 50],
    6.2,
    1
  );

  // Cable 5: Diagonal Cross-Gorge Cable (East to West)
  renderPrayerCable(
    [7, mastTopN - 2, 5],
    [3, mastTopS - 2, 50],
    6.2,
    3
  );

  // Radiating anchor lines fanning down to cliffside boulders
  renderPrayerCable([3, mastTopN - 4, 4], [1, getGroundY(1, 1) + 2, 1], 1.0, 0);
  renderPrayerCable([7, mastTopN - 4, 4], [8, getGroundY(8, 1) + 2, 1], 1.0, 3);
